function organizeDashboardLayout() { const workspace = document.querySelector('.workspace'); const viewport = document.querySelector('.viewport-panel'); const rail = document.querySelector('.right-rail'); const footer = document.querySelector('.footer-bar'); const camera = $('cameraPanel'); if (!workspace || !viewport || !rail || !footer || !camera || workspace.querySelector('.dashboard-top')) return; const top = document.createElement('div'); top.className = 'dashboard-top'; const cameraStage = document.createElement('aside'); cameraStage.className = 'camera-stage'; cameraStage.append(camera); top.append(viewport, cameraStage); const operations = document.createElement('section'); operations.className = 'operations-grid'; operations.id = 'operationsGrid'; [...rail.children].forEach(child => { if (child !== camera) operations.append(child) }); workspace.insertBefore(top, footer); workspace.insertBefore(operations, footer); rail.remove() }
organizeDashboardLayout()
const SCENE_SCALE = .24; const METER_LAT = 111000
const DRONE_COLORS = ['#7dd3fc', '#fbbf7a', '#c9a7ff', '#a6df91', '#f184b6', '#8ee2d2']
function lonMeters(lat) { return METER_LAT * Math.max(Math.cos(THREE.MathUtils.degToRad(lat)), .1) }
function homePoint() { return state.data?.home || { lat: 30.362, lon: 78.082, altitude: 1200 } }
function local(point) { const home = homePoint(); return new THREE.Vector3((point.lon - home.lon) * lonMeters(home.lat) * SCENE_SCALE, ((point.altitude || home.altitude || 0) - ((home.altitude || 0) - 40)) * SCENE_SCALE, (point.lat - home.lat) * METER_LAT * SCENE_SCALE) }
function terrainHeight(x, z) { const terrain = state.terrain; const bounds = terrain?.bounds; const grid = terrain?.grid; if (terrain?.source === 'dem' && bounds && grid?.length) { const home = homePoint(); const lat = home.lat + z / (METER_LAT * SCENE_SCALE); const lon = home.lon + x / (lonMeters(home.lat) * SCENE_SCALE); if (lat >= bounds.south && lat <= bounds.north && lon >= bounds.west && lon <= bounds.east) { const row = Math.min(grid.length - 1, Math.max(0, Math.round((bounds.north - lat) / Math.max(bounds.north - bounds.south, 1e-9) * (grid.length - 1)))); const col = Math.min(grid[0].length - 1, Math.max(0, Math.round((lon - bounds.west) / Math.max(bounds.east - bounds.west, 1e-9) * (grid[0].length - 1)))); const elevation = Number(grid[row][col]); if (Number.isFinite(elevation)) return (elevation - Number(home.altitude || 0)) * SCENE_SCALE } } return 8 + 14 * Math.sin(x * .025) + 11 * Math.cos(z * .032) + 6 * Math.sin((x + z) * .016) }
function formatClock(seconds) { const total = Math.max(0, Math.floor(seconds)); return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}` }
function sensorTitle(sensor) { return sensor === 'rgb' ? 'RGB' : sensor === 'thermal' ? 'THERMAL' : sensor === 'multispectral' ? 'MULTISPECTRAL' : 'CHANGE' }
function nextFrameId(prefix = 'frame') { state.frame += 1; return `${prefix}-${String(state.frame).padStart(4, '0')}` }
function setStatus(message, kind = '') { const el = $('operationStatus'); el.textContent = message; el.className = `operation-status ${kind}` }
function requestJson(url, options = {}) { return fetch(url, options).then(async response => { let payload = null; try { payload = await response.json() } catch {} if (!response.ok) throw new Error(payload?.error || `Request failed (${response.status})`); return payload }) }
function updateMapContextStatus() { const badge = $('mapContextBadge'); if (!badge) return; const labels = { 'offline-synthetic': 'OFFLINE SYNTHETIC MAP', osm: 'OSM CONTEXT · EXTERNAL' }; badge.textContent = labels[state.mapContext] || 'MAP CONTEXT'; badge.classList.toggle('external', state.mapContext === 'osm') }
let geoMap = null
let geoLayers = null
function geoIcon(color, label) { return L.divIcon({ className: 'geo-marker-wrap', html: `<span class="geo-marker" style="--marker-color:${color}"></span><b>${label}</b>`, iconSize: [18, 18], iconAnchor: [9, 9] }) }
function initGeoMap() { if (geoMap || !$('geoMap')) return; geoMap = L.map('geoMap', { zoomControl: false, attributionControl: true, preferCanvas: true }).setView([homePoint().lat, homePoint().lon], 13); L.control.zoom({ position: 'bottomright' }).addTo(geoMap); const tiles = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap contributors' }); tiles.on('tileload', () => { $('geoMapStatus').textContent = 'OSM MAP ONLINE'; $('geoMapStatus').classList.add('online') }); tiles.on('tileerror', () => { $('geoMapStatus').textContent = 'OSM UNAVAILABLE · SYNTHETIC FALLBACK'; $('geoMapStatus').classList.remove('online') }); tiles.addTo(geoMap); geoLayers = { sectors: L.layerGroup().addTo(geoMap), routes: L.layerGroup().addTo(geoMap), drones: L.layerGroup().addTo(geoMap), candidates: L.layerGroup().addTo(geoMap), operator: L.layerGroup().addTo(geoMap) }; window.setTimeout(() => geoMap.invalidateSize(), 150); updateGeographicMap(true) }
function updateGeographicMap(fit = false) { if (!geoMap || !geoLayers || !state.data) return; Object.values(geoLayers).forEach(layer => layer.clearLayers()); const bounds = []; cells().forEach((cell, index) => { const color = ['#c65b4c', '#d3a45d', '#8ba879', '#a1b58d'][index % 4]; const marker = L.circle([cell.lat, cell.lon], { radius: Math.sqrt((cell.area_m2 || 25000) / Math.PI), color, weight: 1, fillColor: color, fillOpacity: .18 }).bindTooltip(`${cell.id} · PRIORITY ${cell.priority || index + 1}`); marker.addTo(geoLayers.sectors); bounds.push([cell.lat, cell.lon]) }); const routeSets = state.mode === 'swarm' ? state.routes : { single: effectiveSingleRoute() }; Object.entries(routeSets).forEach(([id, route], index) => { const points = (route || []).map(point => [point.lat, point.lon]); if (points.length > 1) L.polyline(points, { color: state.mode === 'swarm' ? colorForDrone(id, index) : '#e0c97d', weight: 3, opacity: .82 }).bindTooltip(`${id} route`).addTo(geoLayers.routes); points.forEach(point => bounds.push(point)) }); const drones = state.mode === 'swarm' ? [...state.simDrones.values()] : [{ ...getSinglePoint(), drone_id: 'single' }]; drones.forEach((drone, index) => { L.marker([drone.lat, drone.lon], { icon: geoIcon(state.mode === 'swarm' ? colorForDrone(drone.drone_id, index) : '#b9ef9b', drone.drone_id === 'single' ? 'DRONE' : drone.drone_id) }).bindTooltip(`${drone.drone_id} · LIVE POSITION`).addTo(geoLayers.drones); bounds.push([drone.lat, drone.lon]) }); (state.data.detections || []).forEach(detection => { L.marker([detection.lat, detection.lon], { icon: geoIcon('#ed6255', 'CANDIDATE') }).bindPopup(`<strong>Possible candidate</strong><br>${Number(detection.lat).toFixed(6)}, ${Number(detection.lon).toFixed(6)}<br>${Math.round((detection.confidence || 0) * 100)}% confidence`).addTo(geoLayers.candidates); bounds.push([detection.lat, detection.lon]) }); if (state.manualCoordinate) { L.marker([state.manualCoordinate.lat, state.manualCoordinate.lon], { icon: geoIcon('#f0d28e', 'WAYPOINT') }).bindPopup(`<strong>Operator waypoint</strong><br>${state.manualCoordinate.lat.toFixed(6)}, ${state.manualCoordinate.lon.toFixed(6)}`).addTo(geoLayers.operator); bounds.push([state.manualCoordinate.lat, state.manualCoordinate.lon]) } if (fit && bounds.length) geoMap.fitBounds(bounds, { padding: [24, 24], maxZoom: 15 }) }
function markCoordinate() { const lat = Number($('coordinateLat').value); const lon = Number($('coordinateLon').value); if (!Number.isFinite(lat) || lat < -90 || lat > 90 || !Number.isFinite(lon) || lon < -180 || lon > 180) { setStatus('INVALID COORDINATE · USE LATITUDE -90..90 AND LONGITUDE -180..180', 'error'); return } state.manualCoordinate = { lat, lon }; if (geoMap) { geoMap.setView([lat, lon], Math.max(geoMap.getZoom(), 15)); updateGeographicMap(); } state.fieldPacketStatus = 'ready'; updateFieldPacket({ lat, lon, investigated: true }); updateMissionStory('packet'); setStatus(`OPERATOR WAYPOINT MARKED · ${lat.toFixed(6)}, ${lon.toFixed(6)}`, 'success') }
function ensureDetectionIntelligencePanel() { if ($('detectionIntelligence')) return; const panel = document.createElement('section'); panel.id = 'detectionIntelligence'; panel.className = 'detection-intelligence'; panel.innerHTML = '<div class="detection-intelligence-head"><div><span class="section-kicker">HUMAN-SIGN INTELLIGENCE</span><p>People and human-made signs found in aerial imagery</p></div><span id="detectionAnalysisState">READY</span></div><div class="detection-category-grid">' + [['person', 'PEOPLE'], ['clothing', 'CLOTHING'], ['shelter', 'SHELTERS'], ['track', 'TRACKS']].map(([key, label]) => `<div class="detection-category" data-category="${key}"><strong id="count-${key}">0</strong><span>${label}</span><small id="confidence-${key}">NO CUE</small></div>`).join('') + '</div>'; $('detectionPanel').before(panel); const upload = document.createElement('button'); upload.id = 'uploadImage'; upload.type = 'button'; upload.className = 'image-upload-button'; upload.textContent = 'UPLOAD RGB IMAGE'; const input = document.createElement('input'); input.id = 'imageInput'; input.type = 'file'; input.accept = 'image/png,image/jpeg,.png,.jpg,.jpeg'; input.hidden = true; upload.onclick = () => { selectSensor('rgb', true); input.click() }; input.onchange = () => analyzeFrame(input.files[0]); $('loadFrame').before(upload); $('cameraPanel').append(input); renderDetectionIntelligence() }
function renderDetectionIntelligence() { const panel = $('detectionIntelligence'); if (!panel) return; const categories = { person: [], clothing: [], shelter: [], track: [] }; (state.data?.detections || []).forEach(detection => { const labels = String(detection.label || '').toLowerCase().split(/[,;/+]/).map(label => label.trim()); Object.keys(categories).forEach(category => { if (labels.includes(category) || labels.some(label => label.includes(category))) categories[category].push(detection) }) }); Object.entries(categories).forEach(([category, detections]) => { const count = $(`count-${category}`); const confidence = $(`confidence-${category}`); count.textContent = String(detections.length); const latest = detections[0]; confidence.textContent = latest ? `${Math.round((latest.confidence || 0) * 100)}% · ${sensorTitle(latest.band || 'rgb')}` : 'NO CUE'; panel.querySelector(`[data-category="${category}"]`).classList.toggle('has-detection', detections.length > 0) }); const stateLabel = $('detectionAnalysisState'); if (stateLabel) stateLabel.textContent = state.data?.detections?.length ? 'CUES FOUND' : 'READY FOR IMAGE' }
function updateMissionStory(stage) { const order = ['priority', 'scan', 'found', 'investigate', 'packet']; const active = Math.max(0, order.indexOf(stage)); document.querySelectorAll('#missionStory [data-stage]').forEach((item) => { const index = order.indexOf(item.dataset.stage); item.classList.toggle('active', index === active); item.classList.toggle('complete', index < active) }); document.querySelectorAll('#missionStory i').forEach((item, index) => item.classList.toggle('complete', index < active)) }
function updateFieldPacket(candidate) { const status = $('fieldPacketStatus'); const coordinates = $('fieldPacketCoordinates'); if (!status || !coordinates) return; const packet = candidate || state.manualCoordinate; if (!packet) { if (state.fieldPacketStatus === 'ready') return; state.fieldPacketStatus = 'waiting'; status.textContent = 'WAITING FOR A CANDIDATE'; coordinates.textContent = 'No coordinate yet'; $('fieldPacketCard').classList.remove('ready'); return } const coordinate = `${Number(packet.lat).toFixed(6)}, ${Number(packet.lon).toFixed(6)}`; coordinates.textContent = coordinate; if (state.fieldPacketStatus === 'ready' || packet.investigated || packet === state.manualCoordinate) { status.textContent = 'FIELD PACKET READY · HUMAN REVIEW'; $('fieldPacketCard').classList.add('ready'); } else { status.textContent = 'POSSIBLE PERSON · REVIEW REQUIRED'; $('fieldPacketCard').classList.remove('ready') } }
function openOsmContext() { const candidate = (state.data?.detections || []).find(item => !item.investigated) || getSinglePoint() || homePoint(); if (!navigator.onLine) { state.mapContext = 'offline-synthetic'; updateMapContextStatus(); setStatus('OSM UNAVAILABLE OFFLINE · SYNTHETIC MAP REMAINS ACTIVE', 'error'); return } const url = `https://www.openstreetmap.org/?mlat=${encodeURIComponent(candidate.lat)}&mlon=${encodeURIComponent(candidate.lon)}#map=15/${encodeURIComponent(candidate.lat)}/${encodeURIComponent(candidate.lon)}`; window.open(url, '_blank', 'noopener'); state.mapContext = 'osm'; updateMapContextStatus(); setStatus(`OSM CONTEXT OPENED · ${Number(candidate.lat).toFixed(5)}, ${Number(candidate.lon).toFixed(5)}`, 'success') }
