function frameMainView() { const points = [homePoint(), ...cells()]; if (!points.length) return; const xs = points.map(point => local(point).x); const zs = points.map(point => local(point).z); orbitTarget.set((Math.min(...xs) + Math.max(...xs)) / 2, 20, (Math.min(...zs) + Math.max(...zs)) / 2); orbit.radius = Math.max(360, Math.min(760, Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...zs) - Math.min(...zs)) * 1.8)); updateOrbit() }
