function drawMinimap() { if (!state.data) return; const rect = miniCanvas.getBoundingClientRect(); const dpr = Math.min(window.devicePixelRatio || 1, 2); miniCanvas.width = Math.max(rect.width * dpr, 1); miniCanvas.height = Math.max(rect.height * dpr, 1); miniContext.setTransform(dpr, 0, 0, dpr, 0, 0); miniContext.clearRect(0, 0, rect.width, rect.height); miniContext.fillStyle = '#132016'; miniContext.fillRect(0, 0, rect.width, rect.height); const points = [homePoint(), ...cells(), ...(state.data.detections || [])]; const positions = points.map(point => local(point)); const minX = Math.min(...positions.map(point => point.x), -100) - 100; const maxX = Math.max(...positions.map(point => point.x), 100) + 100; const minZ = Math.min(...positions.map(point => point.z), -100) - 100; const maxZ = Math.max(...positions.map(point => point.z), 100) + 100; const scale = Math.min(rect.width / Math.max(maxX - minX, 1), rect.height / Math.max(maxZ - minZ, 1)); const screen = point => { const localPoint = local(point); return { x: (localPoint.x - minX) * scale + (rect.width - (maxX - minX) * scale) / 2, y: (localPoint.z - minZ) * scale + (rect.height - (maxZ - minZ) * scale) / 2 } }; cells().forEach((cell, index) => { const point = screen(cell); miniContext.fillStyle = `${state.mode === 'swarm' ? colorForDrone(state.data.sectors?.find(sector => sector.cell_id === cell.id)?.owning_drone_id, index) : index === 0 ? '#d86a55' : '#708d68'}66`; miniContext.beginPath(); miniContext.arc(point.x, point.y, 18, 0, Math.PI * 2); miniContext.fill(); miniContext.fillStyle = '#d9e5d0'; miniContext.font = '8px ui-monospace, monospace'; miniContext.fillText(cell.id, point.x + 8, point.y - 7) }); if (state.mode === 'single') { miniContext.strokeStyle = '#e0c97d'; miniContext.lineWidth = 2; miniContext.beginPath(); state.route.forEach((routePoint, index) => { const point = screen(routePoint); if (!index) miniContext.moveTo(point.x, point.y); else miniContext.lineTo(point.x, point.y) }); miniContext.stroke() } const home = screen(homePoint()); miniContext.fillStyle = '#edd18d'; miniContext.fillRect(home.x - 4, home.y - 4, 8, 8); (state.data.detections || []).forEach(detection => { const point = screen(detection); miniContext.fillStyle = '#ed6255'; miniContext.beginPath(); miniContext.arc(point.x, point.y, 5, 0, Math.PI * 2); miniContext.fill() }); const dronePoints = state.mode === 'swarm' ? [...state.simDrones.values()] : [getSinglePoint()]; dronePoints.forEach((drone, index) => { const point = screen(drone); miniContext.fillStyle = state.mode === 'swarm' ? colorForDrone(drone.drone_id, index) : '#b9ef9b'; miniContext.beginPath(); miniContext.arc(point.x, point.y, 6, 0, Math.PI * 2); miniContext.fill() }); $('minimapReadout').textContent = state.mode === 'swarm' ? `${state.data.drones?.length || 0} DRONES · OWNERSHIP / COVERAGE · PLANNING ONLY` : `${getSinglePoint().lat.toFixed(5)}, ${getSinglePoint().lon.toFixed(5)} · ${state.terrain?.source === 'dem' ? 'DEM' : 'SIM'} MAP` }

function renderDetections() { const detections = state.data?.detections || []; $('detectionCount').textContent = `${detections.length} CANDIDATE${detections.length === 1 ? '' : 'S'}`; const list = $('detectionList'); list.replaceChildren(); if (!detections.length) { list.innerHTML = '<div class="empty-state">No candidate has been accepted. The queue will show geolocated cues for review.</div>'; updateFieldPacket(null); return } const candidate = detections.find(item => !item.investigated) || detections[0]; updateFieldPacket(candidate); detections.forEach(detection => { const row = document.createElement('article'); row.className = 'detection-row'; const title = document.createElement('strong'); title.textContent = `${String(detection.label || 'CANDIDATE').toUpperCase()} · ${Math.round((detection.confidence || 0) * 100)}%`; const meta = document.createElement('span'); meta.textContent = `${sensorTitle(detection.band || 'rgb')} · ${Number(detection.lat).toFixed(6)}, ${Number(detection.lon).toFixed(6)}${detection.track_id ? ` · ${detection.track_id}` : ''}`; const detail = document.createElement('small'); detail.textContent = `${detection.evidence || 'No evidence note'} · ${detection.source_frame || 'unknown frame'}`; const why = document.createElement('em'); why.textContent = detection.investigated ? 'Cue reviewed; field team can use the exported waypoint.' : 'Possible person cue — confirm this coordinate before dispatch.'; row.append(title, meta, detail, why); const action = document.createElement('button'); action.className = 'quiet-button'; action.type = 'button'; action.textContent = detection.investigated ? 'FIELD PACKET READY' : 'INVESTIGATE COORDINATE'; action.disabled = Boolean(detection.investigated); action.onclick = () => investigateDetection(detection); row.append(action); list.append(row) }) }
