function renderSwarm() { const initialized = Boolean(state.data?.initialized !== false && state.data?.drones?.length); $('swarmEmpty').hidden = initialized; $('swarmRows').replaceChildren(); $('initSwarm').hidden = initialized; if (!initialized) return; const sectors = new Map((state.data.sectors || []).map(sector => [sector.cell_id, sector])); state.data.drones.forEach((drone, index) => { const row = document.createElement('article'); row.className = 'swarm-row'; row.dataset.droneId = drone.drone_id; row.style.setProperty('--drone-color', colorForDrone(drone.drone_id, index)); const id = document.createElement('strong'); id.textContent = drone.drone_id; const status = document.createElement('span'); status.className = `drone-status ${drone.status}`; status.textContent = drone.status === 'investigating' ? 'INVESTIGATE' : drone.status === 'returning' ? 'RETURN TO BASE' : drone.status.toUpperCase(); const sector = document.createElement('span'); sector.textContent = drone.assigned_sector_id || (sectors.get(drone.assigned_sector_id)?.owner_status || 'IDLE'); const battery = document.createElement('span'); battery.textContent = `${Math.round(drone.battery_percent)}%`; row.append(id, status, sector, battery); $('swarmRows').append(row) }) }
function showOnboarding(mode) { if (state.onboardingSeen.has(mode)) return; $('onboardingText').textContent = mode === 'swarm' ? 'Each drone is assigned a sector automatically — press INIT SWARM to begin.' : 'Ranked search areas are shown on the terrain map — the drone is following the route now; use PAUSE to stop it.'; const banner = $('onboardingBanner'); banner.hidden = false; banner.style.display = 'flex' }
