function setModePanels() { const swarm = state.mode === 'swarm'; $('missionCard').hidden = swarm; $('swarmControlPanel').hidden = !swarm; $('tracksPanel').hidden = false; $('swarmControlPanel').classList.toggle('active-panel', swarm); $('missionCard').classList.toggle('active-panel', !swarm); if (swarm) { $('swarmControlPanel').classList.add('active-panel'); $('cameraPanel').open = true } $('modeToggle').textContent = swarm ? 'SINGLE AIRCRAFT' : 'ENTER SWARM MODE'; $('testEvent').textContent = swarm ? 'REPLAY PASS' : 'RUN SENSOR CHECK'; $('airspaceBadge').textContent = swarm ? 'SWARM · PLANNING MODE' : 'LOCAL FIELD REPLAY'; if (swarm) { $('swarmControlPanel').classList.add('mode-entered'); showOnboarding('swarm') } }
function applySingle(payload, fit = false) { state.mode = 'single'; registerIncomingDetections(payload); state.data = payload; state.singleData = payload; state.route = Array.isArray(payload.waypoints) ? payload.waypoints.slice() : []; state.routes = {}; state.satellite = Object.prototype.hasOwnProperty.call(payload, 'satellite_context') ? payload.satellite_context : state.satellite; state.detected = (payload.detections || []).some(detection => !detection.investigated); setModePanels(); $('missionId').textContent = payload.mission_id || 'MISSION'; updateDataSourceStatus(); buildTerrain(); buildLayers(); updateRoute(); updateDetections(); setupDroneMeshes(); renderDetections(); renderTracks(); if (fit) frameMainView() }
