function applyPayload(payload, fit = false) { if (payload?.mode === 'swarm') applySwarm(payload, fit); else applySingle(payload, fit) }
async function sendFrame(file, sensor, frameId, filename) { const requestId = ++state.latestRequestId; const form = new FormData(); form.append('image', file, filename || `${frameId}.jpg`); form.append('sensor', sensor); form.append('metadata', JSON.stringify({ frame_id: frameId, lat: homePoint().lat, lon: homePoint().lon, altitude_m: homePoint().altitude, ground_sample_distance_m: .25, source_type: sensor, crs: 'EPSG:4326', metadata_quality: 'simulated-camera-metadata' })); const payload = await requestJson('/api/frames/detect', { method: 'POST', body: form }); if (requestId >= state.latestAppliedRequestId) { state.latestAppliedRequestId = requestId; applySingle(payload) } }
async function simulatePass() { const target = state.data?.cells?.[0] || homePoint(); state.passCount += 1; const payload = { detections: [{ id: `replay-person-${state.passCount}`, lat: target.lat, lon: target.lon, altitude: target.altitude || 0, confidence: .72, band: 'rgb', source_frame: `swarm-pass-${state.passCount}`, evidence: 'field replay pass; investigation cue' }] }; try { const response = await requestJson('/api/swarm/telemetry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); applySwarm(response); setStatus(`FIELD REPLAY PASS ${state.passCount} · TRACK ASSOCIATED`, 'success') } catch (error) { const existing = state.data?.tracks?.[0]; const track = existing || { track_id: 'TRK-001', lat: target.lat, lon: target.lon, confidence: .72, detection_count: 0, tracking_mode: 'nearest_decay' }; track.detection_count = (track.detection_count || 0) + 1; state.data = { ...state.data, detections: [{ id: track.track_id, track_id: track.track_id, lat: target.lat, lon: target.lon, confidence: track.confidence, label: 'candidate', band: 'rgb' }], tracks: [track] }; renderTracks(); renderDetections(); setStatus('FIELD REPLAY PASS · LOCAL TRACKING', 'success') } }
async function triggerTest() { if (state.mode === 'swarm') { await simulatePass(); return } if (state.detecting || state.busy || state.activeSensor === 'change') return; state.detecting = true; $('testEvent').disabled = true; const frameId = nextFrameId(`test-${state.activeSensor}`); try { const canvas = document.createElement('canvas'); canvas.width = 128; canvas.height = 96; const context = canvas.getContext('2d'); context.fillStyle = '#111'; context.fillRect(0, 0, 128, 96); context.fillStyle = '#f5f5f5'; context.fillRect(57, 30, 14, 36); const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', .9)); await sendFrame(blob, state.activeSensor, frameId); $('sensorState').textContent = `${sensorTitle(state.activeSensor)} ANALYSIS COMPLETE`; setStatus('TEST FRAME COMPLETE', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.detecting = false; $('testEvent').disabled = false } }
async function analyzeFrame(file) { if (!file || state.busy) return; state.busy = 'frame'; const sensor = state.activeSensor; $('loadFrame').disabled = true; try { await sendFrame(file, sensor, nextFrameId(sensor), file.name); $('cameraMode').textContent = `${sensorTitle(sensor)} INPUT LOADED`; $('sensorState').textContent = `${sensorTitle(sensor)} ANALYSIS COMPLETE`; setStatus(`${sensorTitle(sensor)} ANALYSIS COMPLETE`, 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('loadFrame').disabled = false; $('frameInput').value = '' } }
async function analyzeChange() { if (!state.changeFiles.previous || !state.changeFiles.current || state.busy) return; state.busy = 'change'; $('loadChange').disabled = true; try { const form = new FormData(); form.append('previous', state.changeFiles.previous); form.append('current', state.changeFiles.current); form.append('metadata', JSON.stringify({ frame_id: nextFrameId('change'), lat: homePoint().lat, lon: homePoint().lon, altitude_m: homePoint().altitude, source_type: 'change' })); const payload = await requestJson('/api/change-detection', { method: 'POST', body: form }); applySingle(payload, true); const registration = payload.change_registration; $('cameraMode').textContent = 'CHANGE PASS LOADED'; $('sensorState').textContent = registration?.registered ? `REGISTERED · ${Math.round((registration.score || 0) * 100)}% MATCH` : 'REGISTRATION FALLBACK'; setStatus(registration?.registered ? 'CHANGE DETECTION COMPLETE · PASSES REGISTERED' : 'CHANGE DETECTION COMPLETE · CHECK REGISTRATION', registration?.registered ? 'success' : 'error') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('loadChange').disabled = false; state.changeFiles = { previous: null, current: null }; $('previousChangeInput').value = ''; $('currentChangeInput').value = '' } }
async function loadDem(file) { if (!file || state.busy) return; state.busy = 'dem'; try { const form = new FormData(); form.append('dem', file, file.name); const payload = await requestJson('/api/terrain/load', { method: 'POST', body: form }); state.terrain = payload.terrain; applyPayload(payload.mission, true); setStatus('DEM LOADED · TERRAIN ROUTING ACTIVE', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('demInput').value = '' } }
