async function analyzeDataset(file) { if (!file || state.busy) return; state.busy = 'dataset'; try { const form = new FormData(); form.append('dataset', file); const payload = await requestJson('/api/dataset/analyze', { method: 'POST', body: form }); applySingle(payload, true); setStatus('DATASET ANALYSIS COMPLETE', 'success') } catch (error) { setStatus(error.message, 'error') } finally { state.busy = null; $('datasetInput').value = '' } }
function selectSensor(sensor, openCamera = false) { state.activeSensor = sensor; const card = document.querySelector('.camera-card'); if (openCamera) window.setTimeout(() => { $('cameraPanel').open = true }, 0); card.classList.remove('band-rgb', 'band-thermal', 'band-multispectral', 'band-change'); card.classList.add(`band-${sensor}`); document.querySelectorAll('[data-sensor]').forEach(button => { const selected = button.dataset.sensor === sensor; button.classList.toggle('active', selected); button.setAttribute('aria-selected', String(selected)) }); $('sensorState').textContent = sensor === 'change' ? 'SELECT TWO PASSES TO COMPARE' : `${sensorTitle(sensor)} ANALYSIS READY`; $('loadFrame').hidden = sensor === 'change' || state.mode === 'swarm'; $('testEvent').hidden = sensor === 'change'; $('cameraMode').textContent = sensor === 'change' ? 'CHANGE PASS REVIEW' : `${sensorTitle(sensor)} VIEW` }
function initLayerButtons() { const bindings = [['toggleHeat', 'heat', worldObjects.priority], ['toggleCoverage', 'coverage', worldObjects.coverage], ['toggleNfz', 'nfz', [worldObjects.noFly]]]; bindings.forEach(([id, key, objects]) => { $(id).onclick = () => { state.layers[key] = !state.layers[key]; objects.forEach(object => { if (object) object.visible = state.layers[key] }); $(id).classList.toggle('selected', state.layers[key]); $(id).setAttribute('aria-pressed', String(state.layers[key])); setStatus(`${key.toUpperCase()} LAYER ${state.layers[key] ? 'ON' : 'OFF'}`) } }) }
async function enterSwarm() { if (state.mode === 'single') { try { const payload = await requestJson('/api/swarm'); applySwarm(payload); setStatus(payload.initialized ? 'SWARM CONTROL READY · PLANNING MODE' : 'SWARM MODE · INITIALIZE SEARCH', 'success') } catch { applySwarm({ mode: 'swarm', initialized: false, drones: [], sectors: [], cells: [], detections: [], tracks: [], waypoints: {}, mission_id: state.data?.mission_id }); setStatus('SWARM MODE · API NOT INITIALIZED', 'error') } } else { applySingle(state.singleData || { mission_id: 'MISSION', home: homePoint(), cells: [], waypoints: [] }); setStatus('SINGLE AIRCRAFT MODE') } }
async function initSwarm() { try { const payload = await requestJson('/api/swarm/init', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ drone_count: 4 }) }); state.running = true; applySwarm(payload, true); setStatus('SWARM INITIALIZED · PLANNING ONLY', 'success') } catch (error) { setStatus(error.message, 'error') } }
function updateMissionCopy(phase) { const candidate = (state.data?.detections || []).find(item => !item.investigated); const activeLeg = state.mode === 'swarm' ? 'MULTI-SECTOR' : state.route[Math.min(Math.floor(state.time / 18), Math.max(state.route.length - 1, 0))]?.cell_id || 'HOME'; const copy = phase === 'INVESTIGATE CANDIDATE' ? ['Possible person cue found', candidate ? `${String(candidate.label || 'candidate')} at ${Number(candidate.lat).toFixed(4)}, ${Number(candidate.lon).toFixed(4)} — confirm the coordinate before sending a team.` : 'Review the candidate queue before dispatching a ground team.', 'INVESTIGATE COORDINATE'] : phase === 'RETURN TO BASE' ? ['Protecting the return-home reserve', 'The aircraft is completing the search leg and preserving battery for a safe return.', 'EXPORT FIELD PACKET'] : phase === 'COORDINATED SEARCH' ? ['Coordinating sector coverage', 'Each aircraft is assigned a different sector so the team covers more ground without overlap.', 'REVIEW SWARM COVERAGE'] : phase === 'TAKEOFF / CLIMB' ? ['Starting the aerial search', 'The drone is climbing to the first ranked sector while the planner protects the return reserve.', 'WATCH LIVE CAMERA'] : ['Scanning the highest-likelihood area', `The planner ranked ${activeLeg} using location, movement, terrain, and prior coverage.`, 'WATCH LIVE CAMERA']; $('actionDetail').textContent = copy[1]; $('nextAction').textContent = copy[2]; $('missionCard').dataset.explainer = copy[0] }
function updateUi() { const routeCount = state.mode === 'swarm' ? Math.max(...Object.values(state.routes).map(route => route.length), 1) : state.route.length; const duration = Math.max(routeCount * 18, 1); const progress = Math.min(state.time / duration, 1); const phase = state.mode === 'swarm' ? (state.data?.initialized === false ? 'SWARM STANDBY' : 'COORDINATED SEARCH') : state.time < 8 && state.running ? 'TAKEOFF / CLIMB' : state.detected ? 'INVESTIGATE CANDIDATE' : state.time > duration - 18 && state.running ? 'RETURN TO BASE' : state.running ? 'SEARCH SECTOR' : state.time ? 'PAUSED' : 'STANDBY'; updateMissionCopy(phase); $('missionState').textContent = state.running ? 'LIVE' : 'PAUSED'; $('airspaceBadge').textContent = state.mode === 'swarm' ? 'SWARM · PLANNING ONLY' : 'SIMULATION ONLY'; $('railPhase').textContent = phase; $('railStatusDetail').textContent = state.mode === 'swarm' ? 'Drones share coverage across assigned sectors' : state.running ? 'Following the ranked route across the search sectors' : 'Ready to follow the ranked route'; const battery = state.mode === 'swarm' ? Math.round((state.data?.drones || []).reduce((sum, drone) => sum + Number(drone.battery_percent || 0), 0) / Math.max((state.data?.drones || []).length, 1)) : Math.max(36, Math.round(100 - state.time / (duration + 12) * 58)); $('battery').textContent = `${battery}%`; $('coverage').textContent = `${Math.round((state.mode === 'swarm' ? Number(state.data?.swarm_coverage_fraction || 0) : progress) * 100)}%`; $('elapsed').textContent = formatClock(state.time); $('batteryLine').textContent = `${battery}%`; $('batteryMeter').style.width = `${battery}%`; $('action').textContent = phase === 'STANDBY' ? 'READY TO SEARCH' : phase; $('statusChip').textContent = state.mode === 'swarm' ? 'PLANNING' : state.detected ? 'REVIEW' : state.running ? 'RUNNING' : 'READY'; $('altitude').textContent = '35 m'; $('speed').textContent = state.running ? '8.0 m/s' : '0.0 m/s'; $('activeLeg').textContent = state.mode === 'swarm' ? 'MULTI-SECTOR' : state.route[Math.min(Math.floor(state.time / 18), state.route.length - 1)]?.cell_id || 'HOME → RIDGE-01'; $('reserve').textContent = state.mode === 'swarm' ? 'SIMULATED' : `${Math.max(8, Math.round(18 - state.time / 60))} min`; $('phaseLabel').textContent = phase; $('timelineProgress').style.width = `${progress * 100}%`; renderSwarm(); renderTracks(); drawMinimap() }
function normalizeOperationalUi() { const badge = $('airspaceBadge'); if (badge) { badge.textContent = state.mode === 'swarm' ? 'SWARM · PLANNING MODE' : 'LOCAL FIELD REPLAY'; badge.className = 'readiness-badge fallback' } const reserve = $('reserve'); if (state.mode === 'swarm' && reserve) reserve.textContent = 'PROTECTED'; const status = $('operationStatus'); if (status && status.textContent.includes('SIMULATION')) status.textContent = status.textContent.replaceAll('SIMULATION', 'FIELD REPLAY'); const cameraMode = $('cameraMode'); if (cameraMode && cameraMode.textContent.includes('SYNTHETIC')) cameraMode.textContent = cameraMode.textContent.replaceAll('SYNTHETIC', 'FIELD'); renderDetectionIntelligence() }
function initInput() { const element = renderer.domElement; element.addEventListener('pointerdown', event => { dismissOnboarding(); orbit.down = true; orbit.x = event.clientX; orbit.y = event.clientY; element.setPointerCapture(event.pointerId) }); element.addEventListener('pointerup', () => { orbit.down = false }); element.addEventListener('pointermove', event => { if (!orbit.down) return; orbit.theta -= (event.clientX - orbit.x) * .006; orbit.phi = THREE.MathUtils.clamp(orbit.phi + (event.clientY - orbit.y) * .006, .32, 1.48); orbit.x = event.clientX; orbit.y = event.clientY }); element.addEventListener('wheel', event => { event.preventDefault(); dismissOnboarding(); orbit.radius = THREE.MathUtils.clamp(orbit.radius + event.deltaY * .22, 300, 900) }, { passive: false }); window.addEventListener('keydown', event => { if (event.target.matches('input, select, textarea')) return; dismissOnboarding(); if (event.key.toLowerCase() === 'r') { orbit = { theta: .7, phi: 1.02, radius: 520, down: false, x: 0, y: 0 }; frameMainView() } }); window.addEventListener('resize', updateRenderers) }
function initCameraControls() { $('droneCameraSelect').onchange = event => { state.activeCameraDrone = event.target.value; $('cameraPanel').open = true; updateRenderers() }; $('cameraPanel').addEventListener('toggle', () => { $('cameraPanel').open = true; updateRenderers() }); $('cameraPanel').open = true }
function initButtons() { $('resetView').onclick = () => { dismissOnboarding(); orbit = { theta: .7, phi: 1.02, radius: 520, down: false, x: 0, y: 0 }; frameMainView() }; $('modeToggle').onclick = enterSwarm; $('initSwarm').onclick = initSwarm; $('toggleMission').onclick = () => { dismissOnboarding(); state.running = !state.running; state.lastAnimationMs = performance.now(); $('toggleMission').textContent = state.running ? 'PAUSE MISSION' : 'RESUME MISSION'; setStatus(state.running ? 'MISSION RUNNING · SIMULATION MOVING' : 'MISSION PAUSED') }; $('restartMission').onclick = async () => { dismissOnboarding(); try { const payload = await requestJson(state.mode === 'swarm' ? '/api/swarm/reset' : '/api/mission/reset', { method: 'POST' }); state.time = 0; state.frame = 0; state.passCount = 0; state.running = false; applyPayload(payload, true); $('toggleMission').textContent = 'START MISSION'; setStatus('MISSION RESET COMPLETE', 'success') } catch (error) { setStatus(error.message, 'error') } }; $('testEvent').onclick = triggerTest; $('loadFrame').onclick = () => $('frameInput').click(); $('frameInput').onchange = () => analyzeFrame($('frameInput').files[0]); $('loadDem').onclick = () => $('demInput').click(); $('demInput').onchange = () => loadDem($('demInput').files[0]); $('loadSatellite').onclick = () => $('satelliteInput').click(); $('satelliteInput').onchange = () => loadSatellite($('satelliteInput').files[0]); $('loadChange').onclick = () => { if (!state.changeFiles.previous) $('previousChangeInput').click(); else if (!state.changeFiles.current) $('currentChangeInput').click(); else analyzeChange() }; $('previousChangeInput').onchange = () => { state.changeFiles.previous = $('previousChangeInput').files[0] || null; if (state.changeFiles.previous) $('currentChangeInput').click() }; $('currentChangeInput').onchange = () => { state.changeFiles.current = $('currentChangeInput').files[0] || null; if (state.changeFiles.current) analyzeChange() }; $('uploadDataset').onclick = () => $('datasetInput').click(); $('datasetInput').onchange = () => analyzeDataset($('datasetInput').files[0]); $('exportPacket').onclick = async () => { const format = $('exportFormat').value; const response = await fetch(`/api/mission/export?format=${encodeURIComponent(format)}`); const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `kairodristi-field-packet.${format}`; link.click(); setStatus(`${format.toUpperCase()} FIELD PACKET EXPORTED`, 'success') }; document.querySelectorAll('[data-sensor]').forEach(button => { button.onclick = event => { event.preventDefault(); event.stopPropagation(); selectSensor(button.dataset.sensor, true) } }) }
function refreshStoryState() { const detections = state.data?.detections || []; const candidate = detections.find(item => !item.investigated) || detections[0]; const stage = state.fieldPacketStatus === 'ready' ? 'packet' : candidate && state.detected ? 'investigate' : state.detected ? 'found' : state.running ? 'scan' : 'priority'; updateMissionStory(stage); updateFieldPacket(candidate); updateMapContextStatus(); state.geoTick = (state.geoTick + 1) % 6; if (geoMap && state.geoTick === 0) { updateGeographicMap(!state.geoFitted); state.geoFitted = true } }
function animate(now = performance.now()) { requestAnimationFrame(animate); const delta = Math.min(Math.max((now - state.lastAnimationMs) / 1000, 0), .25); state.lastAnimationMs = now; if (state.running) { state.time += delta; if (state.mode === 'single' && !state.detected && !state.detecting && !state.autoDetectionAttempted && state.time > 34) { state.autoDetectionAttempted = true; triggerTest() } if (state.time > Math.max(effectiveSingleRoute().length * 18 + 12, 1) && state.mode === 'single') state.time = 0 } moveDrones(delta); refreshStoryState(); updateUi(); normalizeOperationalUi(); updateOrbit(); renderer.render(scene, camera); cameraRenderer.render(scene, droneCamera) }
async function boot() { try { const [mission, terrain, readiness, swarm] = await Promise.all([requestJson('/api/mission'), requestJson('/api/terrain'), requestJson('/api/readiness'), requestJson('/api/swarm').catch(() => null)]); state.terrain = terrain; state.satellite = mission.satellite_context || null; if (swarm?.initialized) applySwarm(swarm); else applySingle(mission); $('readinessBadge').textContent = `${readiness.model_loaded ? 'YOLO READY' : String(readiness.detector_mode || 'OPENCV').toUpperCase()} · ${readiness.planner_ready ? 'PLANNER READY' : 'NO DEM'}`; $('readinessBadge').className = `readiness-badge ${readiness.model_loaded ? 'ready' : 'fallback'}`; updateDataSourceStatus(); buildTrees(); initInput(); initButtons(); initCameraControls(); initGeoMap(); $('dismissOnboarding').onclick = dismissOnboarding; initLayerButtons(); selectSensor('rgb'); updateDroneCameraOptions(); updateRenderers(); frameMainView(); state.running = true; $('toggleMission').textContent = 'PAUSE MISSION'; showOnboarding('single'); setStatus('LIVE DRONE TRACK ACTIVE', 'success'); state.lastAnimationMs = performance.now(); requestAnimationFrame(animate) } catch (error) { app.innerHTML = `<main class="error-state"><h1>Mission console unavailable</h1><p>${error.message}</p><p>Start the API with <code>py -3.11 -m app.server</code>.</p><button type="button" onclick="location.reload()">RETRY CONNECTION</button></main>` } }
async function refreshAirspace() { state.airspace = await requestJson('/api/airspace').catch(() => ({ source: 'unavailable', available: false, aircraft: [] })); const badge = $('airspaceBadge'); if (badge) { badge.textContent = state.mode === 'swarm' ? 'SWARM · PLANNING MODE' : 'LOCAL FIELD REPLAY'; badge.className = 'readiness-badge fallback' }; drawMinimap() }
boot(); setTimeout(refreshAirspace, 250)
